for (const item of $input.all()) {
  if (!item.binary) continue;

  const soloPDF = {};
  let i = 0;

  for (const key of Object.keys(item.binary)) {
    const archivo = item.binary[key];
    const nombre = (archivo.fileName || '').toLowerCase();

    if (archivo.mimeType === 'application/pdf' || nombre.endsWith('.pdf')) {
      soloPDF[`documento_pdf_${i}`] = archivo;
      i++;
    }
  }

  item.binary = soloPDF;
  item.json.numPDFs = i;
  console.log(item);
}

return $input.all();

// Mismo criterio que "Filtramos firmas": PDF por tipo o por extensión (algunos llegan como application/octet-stream)
const esPdf = adjunto => adjunto.mimeType === 'application/pdf' || (adjunto.fileName || '').toLowerCase().endsWith('.pdf');
const results = [];

for (const item of $input.all()) {
  for (const [clave, adjunto] of Object.entries(item.binary || {})) {
    if (!esPdf(adjunto)) continue;

    results.push({
      json: {
        asunto: item.json.subject,
        remitente: item.json.from,
        nombreArchivo: adjunto.fileName,
      },
      binary: { data: { ...adjunto, mimeType: 'application/pdf' } },
    });
  }
}

return results;

return $input.all().map((item, i) => {
  const preparacion = $('Preparacion Gemini').itemMatching(i).json;
  const separacion = $('Preparar extraer PDF').itemMatching(i);
  const texto = item.json.candidates?.[0]?.content?.parts?.[0]?.text ?? '';

  let datos;
  try {
    datos = JSON.parse(texto.replace(/```json|```/g, '').trim());
  } catch (e) {
    datos = { error: 'Respuesta no válida', respuestaOriginal: texto };
  }

  return {
    json: {
      nombreArchivo: preparacion.nombreArchivo,
      asunto: preparacion.asunto,
      ...datos,
    },
    binary: { data: separacion.binary.data },
  };
});

