// Una sola liquidación por correo: la factura con más confianza según Gemini o, si no marca ninguna, el primer PDF. El resto van como adjuntos
const items = $input.all();
const candidatos = items
  .map((item, i) => ({
    i,
    confianza: Number(item.json.confianza) || 0,
    esFactura: item.json.indice_factura !== null && item.json.indice_factura !== undefined && !item.json.error
  }))
  .filter(c => c.esFactura)
  .sort((a, b) => b.confianza - a.confianza);
const elegido = candidatos.length ? candidatos[0].i : 0;

return items.map((item, i) => ({
  json: { ...item.json, es_liquidacion: i === elegido, factura_detectada: candidatos.length > 0 },
  binary: item.binary,
  pairedItem: i
}));

